const $ = (s) => document.querySelector(s);
const money = (n) => new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', maximumFractionDigits: 0 }).format(n || 0);
const escapeHTML = (value) => String(value ?? '').replace(/[&<>'"]/g, (char) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', "'": '&#39;', '"': '&quot;' })[char]);
let merchantCache = [], methodCache = [], ipRuleCache = [], paymentState = { page: 1, pages: 1 }, ledgerState = { page: 1, pages: 1 }, activeProjectId = ''; let selectedPaymentId = null; let searchTimer;

async function api(url, options = {}) { const res = await fetch(url, { credentials: 'same-origin', headers: { 'content-type': 'application/json', ...(options.headers || {}) }, ...options }); const json = await res.json(); if (!res.ok) { const error = new Error(json.error?.message || 'Request gagal'); error.status = res.status; throw error; } return json; }
let modalReturnFocus=null,verificationResolve=null,verificationBusy=false,refundBusy=false;
const rememberFocus=()=>{modalReturnFocus=document.activeElement;};const restoreFocus=()=>{const target=modalReturnFocus;modalReturnFocus=null;if(target?.isConnected)setTimeout(()=>target.focus(),0);};
function closeVerification(result=false){if(verificationBusy)return;$('#verification-modal').hidden=true;const resolve=verificationResolve;verificationResolve=null;restoreFocus();resolve?.(result);}
function openVerificationModal({title,description,confirmLabel='Konfirmasi',tone='warning'}){if(verificationResolve)closeVerification(false);rememberFocus();$('#verification-title').textContent=title;$('#verification-description').textContent=description;$('#verification-error').textContent='';$('#verification-symbol').textContent=tone==='danger'?'!':'?';$('#verification-symbol').className=`modal-symbol ${tone}`;$('#confirm-verification').textContent=confirmLabel;$('#confirm-verification').className=`verification-confirm ${tone}`;$('#verification-modal').hidden=false;setTimeout(()=>$('#cancel-verification').focus(),0);return new Promise((resolve)=>{verificationResolve=resolve;});}
function showNoticeModal({title='Informasi',description='',tone='info',content=''}){rememberFocus();$('#notice-title').textContent=title;$('#notice-description').textContent=description;$('#notice-symbol').textContent=tone==='error'?'!':'i';$('#notice-symbol').className=`modal-symbol ${tone}`;$('#notice-kicker').textContent=tone==='error'?'TINDAKAN GAGAL':'INFORMASI';$('#notice-content').hidden=!content;$('#notice-content').innerHTML=content;$('#notice-modal').hidden=false;setTimeout(()=>$('#confirm-notice').focus(),0);}
function closeNotice(){ $('#notice-modal').hidden=true;restoreFocus(); }
function closeRefund(){if(refundBusy)return;$('#refund-modal').hidden=true;restoreFocus();}
function openRefundModal(){rememberFocus();$('#refund-form').reset();$('#refund-reason').value='Customer request';$('#refund-error').textContent='';$('#confirm-refund').disabled=false;$('#confirm-refund').textContent='Proses refund';$('#refund-modal').hidden=false;setTimeout(()=>$('#refund-amount').focus(),0);}
function showDashboard(user) { $('#login').hidden = true; $('#dashboard').hidden = false; document.body.classList.remove('session-checking'); loadWorkspaceSwitcher(user?.workspace?.id); const initials=(user?.name||'EvoPay').split(/\s+/).map((part)=>part[0]).join('').slice(0,2).toUpperCase(); document.querySelectorAll('.avatar,.avatar-button').forEach((item)=>item.textContent=initials); const profile=$('.sidebar-profile div'); if(profile&&user){profile.innerHTML=`<b>${escapeHTML(user.name)}</b><small>${escapeHTML(user.role)} · ${escapeHTML(user.email)}</small>`;} view('overview'); }
async function restoreSession() { document.body.classList.add('session-checking'); try { const {data}=await api('/admin/api/session'); showDashboard(data.user); } catch (error) { $('#dashboard').hidden=true; $('#login').hidden=false; document.body.classList.remove('session-checking'); if(error.status!==401) $('#login-error').textContent='Sesi tidak dapat diperiksa. Silakan coba lagi.'; } }
function paymentsHTML(items, interactive = false) { return items.length ? items.map((p) => `<div class="payment-row ${interactive ? 'inspect-payment' : ''}" ${interactive ? `data-payment-id="${escapeHTML(p.id)}" tabindex="0" role="button"` : ''}><div><b>${escapeHTML(p.order_id)}</b><span>${escapeHTML(p.merchant_name || p.id)} · ${new Date(p.created_at).toLocaleString('id-ID')}</span></div><span>${escapeHTML(p.payment_method)}</span><i class="badge ${escapeHTML(p.status)}">${escapeHTML(p.status)}</i><div class="amount">${money(p.total_amount)}</div></div>`).join('') : '<div class="empty-state"><b>No transactions found</b><span>Try adjusting the active filters.</span></div>'; }
function credentialsHTML(key) { return `<b>Save this API key now — it will not be shown again.</b><code>${escapeHTML(key)}</code><button class="copy-key" data-key="${escapeHTML(key)}">Copy API key</button>`; }
function filterParams(includePage = true) { const params = new URLSearchParams(); new FormData($('#payment-filters')).forEach((value, key) => { if (value) params.set(key, value); }); if (includePage) { params.set('page', paymentState.page); params.set('limit', '20'); } return params; }

async function loadWorkspaceSwitcher(activeId){const select=$('#workspace-switcher');try{const {data}=await api('/admin/api/workspaces');select.innerHTML=data.map(w=>`<option value="${escapeHTML(w.id)}">${escapeHTML(w.name)}</option>`).join('');if(activeId)select.value=activeId;}catch{select.innerHTML='<option>Workspace unavailable</option>';select.disabled=true;}}
$('#workspace-switcher').onchange=async event=>{event.target.disabled=true;try{await api(`/admin/api/workspaces/${encodeURIComponent(event.target.value)}/activate`,{method:'POST'});location.reload();}catch(error){event.target.disabled=false;showNoticeModal({title:'Workspace gagal diganti',description:error.message,tone:'error'});}};
async function loadProjectSwitcher(){if(!merchantCache.length)merchantCache=(await api('/admin/api/merchants')).data;const select=$('#project-switcher');if(!merchantCache.length){select.innerHTML='<option value="">Belum ada project</option>';activeProjectId='';return;}if(!activeProjectId||!merchantCache.some(m=>m.id===activeProjectId))activeProjectId=merchantCache[0].id;select.innerHTML=merchantCache.map(m=>`<option value="${escapeHTML(m.id)}">${escapeHTML(m.name)}</option>`).join('');select.value=activeProjectId;}
async function projectOverview(){if(!activeProjectId)return;const {data}=await api(`/admin/api/projects/${activeProjectId}/overview`),t=data.totals;$('#balance-cards').innerHTML=[['Saldo tersedia',money(t.available),'Dana pembayaran berhasil'],['Dana pending',money(t.clearing),'Menunggu konfirmasi'],['Transaksi sukses',t.paid||0,`${Number(t.success_rate).toFixed(1)}% success rate`],['Webhook perlu dicek',data.webhooks.attention,'Delivery gagal atau retry']].map(([label,value,hint],index)=>`<article class="balance-card metric-${index}"><span>${label}</span><strong>${value}</strong><small>${hint}</small></article>`).join('');$('#period-cards').innerHTML=`<article class="period-card"><span>Project aktif</span><strong>${escapeHTML(data.merchant.name)}</strong><small>${data.merchant.callback_url?'Webhook terkonfigurasi':'Webhook belum dikonfigurasi'}</small></article><article class="period-card accent"><span>Channel teratas</span><strong>${escapeHTML(data.methods[0]?.payment_method||'—')}</strong><small>${data.methods[0]?.transactions||0} transaksi dalam 30 hari</small></article>`;}
async function loadLedger(){if(!activeProjectId)return;$('#ledger-list').innerHTML='<div class="loading-state">Memuat mutasi project…</div>';try{const r=await api(`/admin/api/projects/${activeProjectId}/ledger?page=${ledgerState.page}&limit=30`);ledgerState.pages=r.meta.pages;$('#ledger-list').innerHTML=r.data.map(x=>operationsRow(x.description||x.reference_type,`${x.account_name} · ${dateTime(x.created_at)}`,x.direction,`<b class="ledger-amount ${x.direction.toLowerCase()}">${x.direction==='CREDIT'?'+':'−'}${money(x.amount)}</b>`)).join('')||'<div class="empty-state"><b>Belum ada mutasi</b><span>Transaksi berhasil akan muncul di ledger ini.</span></div>';$('#ledger-page-label').textContent=`Halaman ${r.meta.page} dari ${r.meta.pages}`;$('#ledger-prev').disabled=r.meta.page<=1;$('#ledger-next').disabled=r.meta.page>=r.meta.pages;}catch(error){$('#ledger-list').innerHTML=`<div class="empty-state"><b>Mutasi tidak dapat dimuat</b><span>${escapeHTML(error.message)}</span></div>`;}}
async function overview(){const root=$('#overview-view');root.style.opacity='0.5';try{await loadProjectSwitcher();const [project,payments]=await Promise.all([api(`/admin/api/projects/${activeProjectId}/overview`),api(`/admin/api/payments?merchant_id=${encodeURIComponent(activeProjectId)}&limit=10`)]);const data=project.data,t=data.totals;$('#balance-cards').innerHTML=[['Saldo tersedia',money(t.available),'Dana pembayaran berhasil'],['Dana pending',money(t.clearing),'Menunggu konfirmasi'],['Transaksi sukses',t.paid||0,`${Number(t.success_rate).toFixed(1)}% success rate`],['Webhook perlu dicek',data.webhooks.attention,'Delivery gagal atau retry']].map(([label,value,hint],index)=>`<article class="balance-card metric-${index}"><span>${label}</span><strong>${value}</strong><small>${hint}</small></article>`).join('');$('#period-cards').innerHTML=`<article class="period-card"><span>Project aktif</span><strong>${escapeHTML(data.merchant.name)}</strong><small>${data.merchant.callback_url?'Webhook terkonfigurasi':'Webhook belum dikonfigurasi'}</small></article><article class="period-card accent"><span>Channel teratas</span><strong>${escapeHTML(data.methods[0]?.payment_method||'—')}</strong><small>${data.methods[0]?.transactions||0} transaksi dalam 30 hari</small></article>`;$('#recent-payments').innerHTML=paymentsHTML(payments.data.slice(0,6));$('#chart-total').textContent=money(t.available);const max=Math.max(...data.methods.map(x=>x.transactions),1);$('#transaction-chart').innerHTML=`<div class="chart-bars">${data.methods.map(item=>`<div class="chart-column"><div class="bar-value">${item.transactions}</div><div class="bar-track"><i style="height:${Math.max(8,item.transactions/max*100)}%"></i></div><span>${escapeHTML(item.payment_method)}</span></div>`).join('')}</div>`;}catch(error){$('#balance-cards').innerHTML=`<div class="empty-state"><b>Dashboard project tidak dapat dimuat</b><span>${escapeHTML(error.message)}</span></div>`;}finally{root.style.opacity='1';}}
async function populateMerchantFilter() { if (!merchantCache.length) merchantCache = (await api('/admin/api/merchants')).data; const selected = $('#merchant-filter').value; $('#merchant-filter').innerHTML = '<option value="">All merchants</option>' + merchantCache.map((m) => `<option value="${escapeHTML(m.id)}">${escapeHTML(m.name)}</option>`).join(''); $('#merchant-filter').value = selected; }
async function loadPayments() { $('#payments-list').innerHTML = '<div class="loading-state">Scanning transaction orbit…</div>'; try { const result = await api(`/admin/api/payments?${filterParams()}`); paymentState.pages = result.meta.pages; $('#payments-list').innerHTML = paymentsHTML(result.data, true); $('#ledger-summary').innerHTML = `<b>${result.meta.total} transactions</b><span>${money(result.meta.value)} filtered volume</span>`; $('#payment-page-label').textContent = `Page ${result.meta.page} of ${result.meta.pages}`; $('#payments-prev').disabled = result.meta.page <= 1; $('#payments-next').disabled = result.meta.page >= result.meta.pages; bindPaymentRows(); } catch (error) { $('#payments-list').innerHTML = `<div class="empty-state"><b>Could not load payments</b><span>${escapeHTML(error.message)}</span></div>`; } }
function bindPaymentRows() { document.querySelectorAll('.inspect-payment').forEach((row) => { row.onclick = () => openPayment(row.dataset.paymentId); row.onkeydown = (event) => { if (['Enter', ' '].includes(event.key)) openPayment(row.dataset.paymentId); }; }); }
async function merchants() { $('#merchants-view').style.opacity = '0.5'; const data = await api('/admin/api/merchants'); merchantCache = data.data; $('#merchants-list').innerHTML = data.data.map((m) => `<article class="merchant-row"><div><b>${escapeHTML(m.name)}</b><span>${escapeHTML(m.id)}${m.callback_url ? ' · webhook enabled' : ' · no webhook'}</span></div><div class="merchant-controls"><i class="merchant-state ${m.is_active ? 'active' : 'inactive'}">${m.is_active ? 'ACTIVE' : 'DISABLED'}</i><button class="manage-merchant" data-merchant-id="${escapeHTML(m.id)}">Manage</button></div></article>`).join('') || '<p style="color:var(--muted)">Belum ada merchant.</p>'; document.querySelectorAll('.manage-merchant').forEach((button) => { button.onclick = () => openMerchant(button.dataset.merchantId); }); $('#merchants-view').style.opacity = '1'; }
async function paymentMethods(){if(!merchantCache.length)merchantCache=(await api('/admin/api/merchants')).data;const select=$('#method-merchant');const current=select.value||merchantCache[0]?.id||'';select.innerHTML=merchantCache.map((m)=>`<option value="${escapeHTML(m.id)}">${escapeHTML(m.name)}</option>`).join('');select.value=current;if(!current){$('#method-grid').innerHTML='<div class="empty-state"><b>Belum ada merchant</b></div>';return;}$('#method-grid').innerHTML='<div class="loading-state">Memuat channel EvoPay…</div>';methodCache=(await api(`/admin/api/merchants/${current}/payment-methods`)).data;renderPaymentMethods();}
function feeLabel(m){const parts=[];if(m.admin_fee_fixed)parts.push(money(m.admin_fee_fixed));if(m.admin_fee_percentage)parts.push(`${Number(m.admin_fee_percentage).toLocaleString('id-ID')}%`);return parts.join(' + ')||'Gratis';}
const PAYMENT_LOGOS=Object.freeze({BRIVA:'https://www.google.com/s2/favicons?domain=bri.co.id&sz=128',BCAVA:'https://www.google.com/s2/favicons?domain=bca.co.id&sz=128',BNIVA:'https://www.google.com/s2/favicons?domain=bni.co.id&sz=128',MANDIRIVA:'https://www.google.com/s2/favicons?domain=bankmandiri.co.id&sz=128',PERMATAVA:'https://www.google.com/s2/favicons?domain=permatabank.com&sz=128',PERMATAVAA:'https://www.google.com/s2/favicons?domain=permatabank.com&sz=128',CIMBVA:'https://www.google.com/s2/favicons?domain=cimbniaga.co.id&sz=128',DANAMONVA:'https://www.google.com/s2/favicons?domain=danamon.co.id&sz=128',BSIVA:'https://www.google.com/s2/favicons?domain=bankbsi.co.id&sz=128',BNCVA:'https://www.google.com/s2/favicons?domain=neobank.co.id&sz=128',SHOPEEPAY:'https://cdn.simpleicons.org/shopee/ee4d2d',SHOPEEPAY_REALTIME:'https://cdn.simpleicons.org/shopee/ee4d2d',GOPAY:'https://www.google.com/s2/favicons?domain=gopay.co.id&sz=128',GOPAY_REALTIME:'https://www.google.com/s2/favicons?domain=gopay.co.id&sz=128',DANA:'https://www.google.com/s2/favicons?domain=dana.id&sz=128',DANA_REALTIME:'https://www.google.com/s2/favicons?domain=dana.id&sz=128',LINKAJA:'https://www.google.com/s2/favicons?domain=linkaja.id&sz=128',OVOPUSH:'https://www.google.com/s2/favicons?domain=ovo.id&sz=128',OVOPUSH_REALTIME:'https://www.google.com/s2/favicons?domain=ovo.id&sz=128',VIRGO:'https://www.google.com/s2/favicons?domain=virgopos.id&sz=128',ASTRAPAY:'https://www.google.com/s2/favicons?domain=astrapay.com&sz=128',QRIS:'https://www.google.com/s2/favicons?domain=bi.go.id&sz=128',QRISREALTIME:'https://www.google.com/s2/favicons?domain=bi.go.id&sz=128',QRIS_CUSTOM:'https://www.google.com/s2/favicons?domain=bi.go.id&sz=128',ALFAMART:'https://www.google.com/s2/favicons?domain=alfamart.co.id&sz=128',INDOMARET:'https://www.google.com/s2/favicons?domain=indomaret.co.id&sz=128'});
function providerLogo(m){const initials=escapeHTML(m.name.slice(0,2).toUpperCase()),url=PAYMENT_LOGOS[m.code];return `<div class="catalog-logo"><span class="provider-monogram">${initials}</span>${url?`<img src="${url}" alt="Logo ${escapeHTML(m.name)}" loading="lazy" referrerpolicy="no-referrer" onerror="this.remove()">`:''}</div>`;}
function renderPaymentMethods(){const query=$('#method-search').value.trim().toLowerCase(),category=$('#method-category').value,status=$('#method-status').value;const shown=methodCache.filter(m=>(!query||`${m.name} ${m.code}`.toLowerCase().includes(query))&&(!category||m.category===category)&&(!status||(status==='active')===m.is_enabled));const active=methodCache.filter(m=>m.is_enabled).length;$('#method-stat').innerHTML=`<b>${active}</b> / ${methodCache.length} channel aktif`;const names={VIRTUAL_ACCOUNT:'Virtual Account',E_MONEY:'E-Money',QRIS:'QRIS',RETAIL:'Retail'};const card=m=>`<article class="catalog-card ${m.is_enabled?'enabled':''} ${m.requires_registration?'registration':''}"><div class="catalog-card-top">${providerLogo(m)}<div class="catalog-name"><h3>${escapeHTML(m.name)}</h3><span>${escapeHTML(m.code)}</span></div><button class="method-toggle" data-code="${escapeHTML(m.code)}" ${m.requires_registration?'disabled':''} aria-label="${m.requires_registration?'Memerlukan pendaftaran':m.is_enabled?'Nonaktifkan':'Aktifkan'} ${escapeHTML(m.name)}" aria-pressed="${m.is_enabled}"><i></i></button></div><div class="catalog-state">${m.is_enabled?'Aktif':'Nonaktif'}${m.requires_registration?' <em>PKS diperlukan</em>':''}</div><div class="catalog-fee"><span>Biaya admin</span><b>${feeLabel(m)}</b><div><i class="${m.fee_bearer==='CUSTOMER'?'':''}">Merchant</i><i class="${m.fee_bearer==='CUSTOMER'?'selected':''}">Pembeli</i></div></div><div class="catalog-details"><span>◷ Settlement ${escapeHTML(m.settlement_label)}</span><span>⌁ ${money(m.minimum_amount)} — ${m.maximum_amount==null?'∞':money(m.maximum_amount)}</span></div><button class="method-config" data-code="${escapeHTML(m.code)}">Atur channel <span>→</span></button></article>`;$('#method-grid').innerHTML=Object.entries(names).map(([key,label])=>{const items=shown.filter(m=>m.category===key);return items.length?`<section class="method-category-group"><div class="category-heading"><h3>${label}</h3><span>${items.length} channel</span></div><div class="catalog-grid">${items.map(card).join('')}</div></section>`:''}).join('')||'<div class="empty-state"><b>Channel tidak ditemukan</b><span>Ubah filter atau kata pencarian.</span></div>';document.querySelectorAll('.method-toggle:not([disabled])').forEach(button=>button.onclick=()=>togglePaymentMethod(button.dataset.code,button));document.querySelectorAll('.method-config').forEach(button=>button.onclick=()=>openMethodConfig(button.dataset.code));}
async function togglePaymentMethod(code,button){const item=methodCache.find((m)=>m.code===code),next=!item.is_enabled;item.is_enabled=next;renderPaymentMethods();try{await api(`/admin/api/merchants/${$('#method-merchant').value}/payment-methods/${encodeURIComponent(code)}`,{method:'PATCH',body:JSON.stringify({is_enabled:next})});}catch(error){item.is_enabled=!next;renderPaymentMethods();showNoticeModal({title:'Metode pembayaran tidak dapat diubah',description:error.message,tone:'error'});}}
function openMethodConfig(code){const m=methodCache.find((item)=>item.code===code);if(!m)return;$('#method-config-code').value=m.code;$('#method-modal-title').textContent=m.name;$('#method-modal-code').textContent=`${m.code} · ${m.category.replace('_',' ')}`;$('#method-fee-fixed').value=m.admin_fee_fixed;$('#method-fee-percentage').value=m.admin_fee_percentage;$('#method-fee-bearer').value=m.fee_bearer;$('#method-settlement').value=m.settlement_label;$('#method-minimum').value=m.minimum_amount;$('#method-maximum').value=m.maximum_amount??'';$('#method-config-error').textContent='';$('#method-modal').hidden=false;}
function closeMethodConfig(){$('#method-modal').hidden=true;}
function operationsRow(title,subtitle,status,action='') { return `<div class="payment-row"><div><b>${escapeHTML(title)}</b><span>${escapeHTML(subtitle)}</span></div><span></span><i class="badge ${escapeHTML(status)}">${escapeHTML(status)}</i><div>${action}</div></div>`; }
async function loadWebhooks(){$('#webhooks-view').style.opacity = '0.5'; const status=$('#webhook-status')?.value||'';const result=await api(`/admin/api/webhooks${status?`?status=${encodeURIComponent(status)}`:''}`);const s=result.summary;$('#webhook-metrics').innerHTML=[['Total deliveries',s.total],['Delivered',s.delivered],['Needs attention',s.failed],['Avg attempts',Number(s.average_attempts).toFixed(1)]].map(([label,value])=>`<article class="balance-card"><span>${label}</span><strong>${value||0}</strong></article>`).join('');$('#webhooks-list').innerHTML=result.data.map((item)=>operationsRow(item.merchant_order_id,`${item.merchant_name} · ${item.event_type} · ${item.attempt_count} attempts`,item.status,item.status!=='DELIVERED'?`<button class="retry-delivery" data-delivery-id="${escapeHTML(item.id)}">Retry</button>`:'' )).join('')||'<div class="empty-state"><b>No webhook deliveries</b><span>Delivery activity will appear here.</span></div>';document.querySelectorAll('.retry-delivery').forEach((button)=>button.onclick=()=>retryDelivery(button.dataset.deliveryId,button)); $('#webhooks-view').style.opacity = '1'; }
async function loadFinance(){$('#finance-view').style.opacity = '0.5'; const [balances,settlements,refunds]=await Promise.all([api('/admin/api/finance/balances'),api('/admin/api/finance/settlements'),api('/admin/api/finance/refunds')]);$('#finance-balances').innerHTML=balances.data.map((item)=>`<article class="balance-card"><span>${escapeHTML(item.merchant.name)}</span><strong>${money(item.available)}</strong><small>${money(item.pending)} pending · ${money(item.settled)} settled</small></article>`).join('');$('#settlements-list').innerHTML=settlements.data.map((item)=>operationsRow(item.merchant_name,money(item.amount),item.status,item.status==='APPROVAL_REQUIRED'?`<button class="approve-settlement" data-id="${escapeHTML(item.id)}">Approve</button>`:'' )).join('')||'<div class="empty-state"><b>No settlements</b><span>Settlement requests will appear here.</span></div>';$('#refunds-list').innerHTML=refunds.data.map((item)=>operationsRow(item.merchant_order_id,`${item.merchant_name} · ${money(item.amount)}`,item.status)).join('')||'<div class="empty-state"><b>No refunds</b><span>Refund history will appear here.</span></div>';document.querySelectorAll('.approve-settlement').forEach((button)=>button.onclick=async()=>{const approved=await openVerificationModal({title:'Setujui settlement?',description:'Dana akan diteruskan ke proses settlement merchant. Pastikan nominal dan merchant sudah sesuai.',confirmLabel:'Setujui settlement'});if(!approved)return;button.disabled=true;try{await api(`/admin/api/finance/settlements/${button.dataset.id}/approve`,{method:'POST'});await loadFinance();}catch(error){showNoticeModal({title:'Settlement gagal disetujui',description:error.message,tone:'error'});button.disabled=false;}}); $('#finance-view').style.opacity = '1'; }
async function loadAnalytics(){$('#analytics-view').style.opacity = '0.5'; const {data}=await api('/admin/api/analytics');$('#analytics-metrics').innerHTML=[['Success rate',`${Number(data.success_rate).toFixed(1)}%`],['Average value',money(data.average_transaction_value)],['Payment methods',data.methods.length]].map(([label,value])=>`<article class="balance-card"><span>${label}</span><strong>${value}</strong></article>`).join('');$('#analytics-status').innerHTML='<h3>Status breakdown</h3>'+data.status.map((x)=>operationsRow(x.status,`${x.count} transactions`,x.status,money(x.nominal))).join('');$('#analytics-methods').innerHTML='<h3>Payment methods</h3>'+data.methods.map((x)=>operationsRow(x.payment_method,`${x.count} transactions`,'ACTIVE',money(x.nominal))).join(''); $('#analytics-view').style.opacity = '1'; }
async function loadAudit(){$('#audit-view').style.opacity = '0.5'; const {data}=await api('/admin/api/audit-logs');$('#audit-list').innerHTML=data.map((item)=>operationsRow(item.action,`${item.actor_name||'System'} · ${new Date(item.created_at).toLocaleString('id-ID')}`,'ACTIVE',escapeHTML(item.target_type||''))).join('')||'<div class="empty-state"><b>No audit activity</b><span>Sensitive actions will be recorded here.</span></div>'; $('#audit-view').style.opacity = '1'; }
function openMerchant(merchantId) { const m = merchantCache.find((item) => item.id === merchantId); if (!m) return; $('#edit-merchant-id').value = m.id; $('#edit-merchant-name').value = m.name; $('#edit-merchant-callback').value = m.callback_url || ''; $('#toggle-merchant-button').textContent = m.is_active ? 'Disable merchant' : 'Enable merchant'; $('#toggle-merchant-button').className = m.is_active ? 'danger-action' : 'enable-action'; $('#merchant-action-error').textContent = ''; $('#rotated-credential').hidden = true; $('#merchant-modal').hidden = false; }
function closeMerchant() { $('#merchant-modal').hidden = true; }
function openDeleteMerchant(){const merchant=merchantCache.find((item)=>item.id===$('#edit-merchant-id').value);if(!merchant)return;$('#delete-merchant-name').textContent=merchant.name;$('#delete-merchant-confirmation').value='';$('#delete-merchant-error').textContent='';$('#confirm-delete-merchant').disabled=true;$('#confirm-delete-merchant').textContent='Hapus permanen';$('#delete-merchant-modal').hidden=false;setTimeout(()=>$('#delete-merchant-confirmation').focus(),0);}
function closeDeleteMerchant(){if($('#confirm-delete-merchant').disabled&&$('#confirm-delete-merchant').textContent==='Menghapus…')return;$('#delete-merchant-modal').hidden=true;}
async function confirmDeleteMerchant(){const button=$('#confirm-delete-merchant'),merchantId=$('#edit-merchant-id').value,confirmation=$('#delete-merchant-confirmation').value;button.disabled=true;button.textContent='Menghapus…';$('#delete-merchant-error').textContent='';try{await api(`/admin/api/merchants/${merchantId}`,{method:'DELETE',body:JSON.stringify({confirmation_name:confirmation})});closeMerchant();$('#delete-merchant-modal').hidden=true;merchantCache=[];methodCache=[];await Promise.all([merchants(),overview()]);}catch(error){$('#delete-merchant-error').textContent=error.message;button.textContent='Hapus permanen';button.disabled=confirmation!==$('#delete-merchant-name').textContent;}}
async function ensureIpMerchants(){if(!merchantCache.length){const response=await api('/admin/api/merchants');merchantCache=response.data;}const select=$('#ip-merchant');const current=select.value;select.innerHTML=merchantCache.map((m)=>`<option value="${escapeHTML(m.id)}">${escapeHTML(m.name)}</option>`).join('');if(current&&merchantCache.some(m=>m.id===current))select.value=current;}
function renderIpRules(summary={total:0,active:0,enforced:false}){$('#ip-enforcement-banner').innerHTML=summary.enforced?'<div class="ip-enforcement secured"><i>✓</i><div><b>Whitelist aktif</b><span>Hanya jaringan aktif di bawah yang dapat mengakses API merchant ini.</span></div></div>':'<div class="ip-enforcement open"><i>!</i><div><b>Akses API masih terbuka</b><span>Tambahkan dan aktifkan minimal satu IP untuk membatasi akses.</span></div></div>';$('#ip-metrics').innerHTML=`<article><span>Rule aktif</span><strong>${summary.active}</strong></article><article><span>Total rule</span><strong>${summary.total}</strong></article><article><span>Mode akses</span><strong class="${summary.enforced?'safe':'warn'}">${summary.enforced?'Terbatas':'Terbuka'}</strong></article>`;$('#ip-rule-count').textContent=`${summary.total} rule`;$('#ip-rules-list').innerHTML=ipRuleCache.length?ipRuleCache.map((rule)=>`<article class="ip-rule-row"><div class="ip-rule-icon">⌁</div><div class="ip-rule-identity"><code>${escapeHTML(rule.cidr)}</code><span>${escapeHTML(rule.label||'Tanpa label')}</span></div><div class="ip-rule-meta"><span>Dibuat ${dateTime(rule.created_at)}</span><span>${rule.last_matched_at?`Terakhir cocok ${dateTime(rule.last_matched_at)}`:'Belum pernah cocok'}</span></div><label class="ip-switch"><input type="checkbox" data-ip-toggle="${escapeHTML(rule.id)}" ${rule.is_active?'checked':''}><span></span><em>${rule.is_active?'Aktif':'Nonaktif'}</em></label><button class="ip-delete" data-ip-delete="${escapeHTML(rule.id)}" type="button">Hapus</button></article>`).join(''):'<div class="ip-empty"><div>♢</div><b>Belum ada IP yang dipercaya</b><span>API merchant dapat diakses dari semua alamat IP.</span><button type="button" data-open-ip-rule>Tambahkan IP pertama</button></div>';document.querySelectorAll('[data-ip-toggle]').forEach(input=>input.onchange=()=>toggleIpRule(input));document.querySelectorAll('[data-ip-delete]').forEach(button=>button.onclick=()=>deleteIpRule(button.dataset.ipDelete));document.querySelectorAll('[data-open-ip-rule]').forEach(button=>button.onclick=openIpRuleModal);}
async function loadIpRules(){await ensureIpMerchants();const merchantId=$('#ip-merchant').value;if(!merchantId){ipRuleCache=[];renderIpRules();return}$('#ip-rules-list').innerHTML='<div class="loading-state">Memuat kebijakan jaringan…</div>';try{const response=await api(`/admin/api/merchants/${merchantId}/ip-allowlist`);ipRuleCache=response.data;renderIpRules(response.summary);}catch(error){showNoticeModal({title:'Whitelist tidak dapat dimuat',description:error.message,tone:'error'});}}
function openIpRuleModal(){if(!$('#ip-merchant').value)return;rememberFocus();$('#ip-rule-form').reset();$('#ip-rule-error').textContent='';$('#ip-rule-modal').hidden=false;setTimeout(()=>$('#ip-rule-cidr').focus(),0);}
function closeIpRuleModal(){if($('#create-ip-rule').disabled)return;$('#ip-rule-modal').hidden=true;restoreFocus();}
async function createIpRule(event){event.preventDefault();const button=$('#create-ip-rule'),body=Object.fromEntries(new FormData(event.target));button.disabled=true;button.textContent='Menambahkan…';$('#ip-rule-error').textContent='';try{await api(`/admin/api/merchants/${$('#ip-merchant').value}/ip-allowlist`,{method:'POST',body:JSON.stringify(body)});button.disabled=false;button.innerHTML='Tambahkan ke whitelist <span>→</span>';closeIpRuleModal();await loadIpRules();}catch(error){$('#ip-rule-error').textContent=error.message;button.disabled=false;button.innerHTML='Tambahkan ke whitelist <span>→</span>';}}
async function toggleIpRule(input){input.disabled=true;try{await api(`/admin/api/merchants/${$('#ip-merchant').value}/ip-allowlist/${input.dataset.ipToggle}`,{method:'PATCH',body:JSON.stringify({is_active:input.checked})});await loadIpRules();}catch(error){input.checked=!input.checked;input.disabled=false;showNoticeModal({title:'Status rule tidak dapat diubah',description:error.message,tone:'error'});}}
async function deleteIpRule(ruleId){const rule=ipRuleCache.find(x=>x.id===ruleId);const approved=await openVerificationModal({title:'Hapus IP dari whitelist?',description:`${rule?.cidr||'Rule ini'} akan dihapus. Jika tidak ada rule aktif tersisa, API kembali terbuka untuk semua IP.`,confirmLabel:'Hapus rule',tone:'danger'});if(!approved)return;try{await api(`/admin/api/merchants/${$('#ip-merchant').value}/ip-allowlist/${ruleId}`,{method:'DELETE'});await loadIpRules();}catch(error){showNoticeModal({title:'Rule tidak dapat dihapus',description:error.message,tone:'error'});}}
let activeCaseId='';async function loadCases(){if(!activeProjectId)return;$('#cases-list').innerHTML='<div class="loading-state">Memuat dispute project…</div>';try{const {data}=await api(`/admin/api/project-cases/${activeProjectId}/disputes`);$('#cases-list').innerHTML=data.map(x=>operationsRow(x.merchant_order_id||x.payment_id,`${x.reason_code||x.reason} · ${x.computed_sla||x.sla_status} · ${dateTime(x.response_due_at||x.updated_at)}`,x.status,`<button class="quiet inspect-case" data-case-id="${escapeHTML(x.id)}">Detail</button>`)).join('')||'<div class="empty-state"><b>Belum ada dispute</b><span>Buka kasus dari pembayaran PAID.</span></div>';document.querySelectorAll('.inspect-case').forEach(button=>button.onclick=()=>loadCaseDetail(button.dataset.caseId));}catch(error){$('#cases-list').innerHTML=`<div class="empty-state"><b>Dispute tidak dapat dimuat</b><span>${escapeHTML(error.message)}</span></div>`;}}async function loadCaseDetail(id){activeCaseId=id;view('case-detail');try{const {data}=await api(`/admin/api/project-cases/${activeProjectId}/disputes/${id}`);$('#case-detail').innerHTML=`<div class="case-summary"><b>${escapeHTML(data.reason_code||data.reason)}</b><span>${money(data.disputed_amount)} · Deadline ${dateTime(data.response_due_at)}</span><i class="badge ${escapeHTML(data.status)}">${escapeHTML(data.status)}</i></div><div class="case-timeline">${data.timeline.map(x=>`<article><i></i><div><b>${escapeHTML(x.to_status)}</b><span>${escapeHTML(x.actor_name||'System')} · ${dateTime(x.created_at)}</span><p>${escapeHTML(x.notes||'')}</p></div></article>`).join('')}</div><h3>Evidence checklist</h3>${data.evidence.map(x=>`<div class="credential-row"><div><b>${escapeHTML(x.checklist_item||x.type)}</b><span>${escapeHTML(x.file_name||x.storage_key)}</span></div><i class="badge ${escapeHTML(x.status)}">${escapeHTML(x.status)}</i></div>`).join('')||'<small>Belum ada evidence.</small>'}`;$('#case-evidence-form').hidden=!['OPEN','INVESTIGATING'].includes(data.status);}catch(error){$('#case-detail-error').textContent=error.message;}}
async function loadNotices(){if(!activeProjectId)return;$('#notices-list').innerHTML='<div class="loading-state">Memuat notifikasi…</div>';try{const {data}=await api(`/admin/api/project-cases/${activeProjectId}/notices`);$('#notices-list').innerHTML=data.map(x=>operationsRow(x.title,`${x.type} · ${dateTime(x.created_at)}`,x.type.includes('DEAD')?'ACTION NEEDED':'NOTICE','')).join('')||'<div class="empty-state"><b>Tidak ada notifikasi</b><span>Project ini tidak memiliki alert operasional saat ini.</span></div>';}catch(error){$('#notices-list').innerHTML=`<div class="empty-state"><b>Notifikasi tidak dapat dimuat</b><span>${escapeHTML(error.message)}</span></div>`;}}
function developerCredentialHTML(items){return items.map(item=>`<article class="credential-row"><div class="credential-mark">⌘</div><div><b>${escapeHTML(item.name)}</b><span><code>${escapeHTML(item.key_prefix)}…</code> · ${escapeHTML(item.environment)} · ${item.scopes.length} scopes</span><small>${item.revoked_at?'REVOKED':item.expires_at?`Expires ${dateTime(item.expires_at)}`:'No expiry'}${item.last_used_at?` · Used ${dateTime(item.last_used_at)}`:''}</small></div><div class="credential-actions">${item.revoked_at?'<i>Revoked</i>':`<button data-rotate-credential="${escapeHTML(item.id)}">Rotate</button><button class="danger" data-revoke-credential="${escapeHTML(item.id)}">Revoke</button>`}</div></article>`).join('')||'<div class="compact-empty">Belum ada API credential.</div>';}
function developerDeliveryHTML(items){return items.map(item=>`<article class="delivery-row"><div><b>${escapeHTML(item.event_type)}</b><span>${escapeHTML(item.status)} · HTTP ${item.response_code||'—'} · ${item.attempt_count} attempt</span><small>${dateTime(item.created_at)}</small></div>${item.status==='DELIVERED'?'<i class="delivery-ok">Delivered</i>':`<button class="retry-delivery" data-project-delivery="${escapeHTML(item.id)}">Replay</button>`}</article>`).join('')||'<div class="compact-empty">Belum ada delivery pada project ini.</div>';}
async function loadApprovals(){try{const [inbox,policies]=await Promise.all([api('/governance/api/approvals'),api('/governance/api/approval-policies')]);$('#approval-list').innerHTML=inbox.data.map(x=>`<article class="control-row"><div><b>${escapeHTML(x.action_type)} · ${money(x.amount)}</b><span>${escapeHTML(x.requester_name||'Unknown')} · ${x.approved_count}/${x.required_approvers} approval</span></div><i class="badge ${escapeHTML(x.status)}">${escapeHTML(x.status)}</i>${x.status==='PENDING'?`<div><button class="approval-decision" data-id="${x.id}" data-decision="APPROVED">Approve</button><button class="approval-decision danger" data-id="${x.id}" data-decision="REJECTED">Reject</button></div>`:''}</article>`).join('')||'<div class="empty-state"><b>Tidak ada approval</b></div>';$('#approval-policy-list').innerHTML=policies.data.map(x=>`<article class="control-row"><div><b>${escapeHTML(x.action_type)}</b><span>Mulai ${money(x.minimum_amount)} · ${x.required_approvers} approver · ${escapeHTML(x.approver_roles.join(', '))}</span></div></article>`).join('');document.querySelectorAll('.approval-decision').forEach(button=>button.onclick=async()=>{try{await api(`/governance/api/approvals/${button.dataset.id}/decision`,{method:'POST',body:JSON.stringify({decision:button.dataset.decision})});loadApprovals();}catch(error){$('#approval-error').textContent=error.message;}});}catch(error){$('#approval-error').textContent=error.message;}}
async function loadOnboarding(){await loadProjectSwitcher();if(!activeProjectId)return;$('#kyc-error').textContent='';try{const [app,gate]=await Promise.all([api(`/admin/api/platform/merchants/${activeProjectId}/onboarding`),api(`/admin/api/platform/merchants/${activeProjectId}/production`)]),data=app.data||{};$('#kyc-status').textContent=data.status||'DRAFT';$('#kyc-status').className=`badge ${data.status||'PENDING'}`;const form=$('#kyc-form');for(const key of ['legal_name','business_type','registration_number','tax_number','business_address','website','bank_name','bank_owner_name'])if(form.elements[key])form.elements[key].value=data[key]||'';$('#kyc-documents').innerHTML=(data.documents||[]).map(x=>`<div class="credential-row"><div><b>${escapeHTML(x.document_type)}</b><span>${escapeHTML(x.file_name)}</span></div><i class="badge ${escapeHTML(x.status)}">${escapeHTML(x.status)}</i></div>`).join('')||'<div class="empty-state"><b>Belum ada dokumen</b></div>';$('#production-checks').innerHTML=Object.entries(gate.data.checks).map(([key,value])=>`<div><i class="${value?'ready':'missing'}">${value?'✓':'!'}</i><span>${escapeHTML(key.replaceAll('_',' '))}</span></div>`).join('');$('#activate-production').disabled=!gate.data.eligible||gate.data.active;$('#activate-production').textContent=gate.data.active?'Production aktif':'Aktifkan production';}catch(error){$('#kyc-error').textContent=error.message;}}
async function loadDeveloper(){if(!activeProjectId)return;try{const [snippet,credentials,deliveries,sessions,scenarios]=await Promise.all([api('/developer/api/snippets',{method:'POST',body:JSON.stringify({language:$('#snippet-language').value,apiKey:'np_sandbox_YOUR_KEY',orderId:$('#snippet-order').value||'ORDER-1001',amount:Number($('#snippet-amount').value)||10000})}),api(`/admin/api/project-developer/${activeProjectId}/credentials`),api(`/admin/api/project-developer/${activeProjectId}/deliveries`),api(`/admin/api/project-developer/${activeProjectId}/sandbox/sessions`),api('/developer/api/sandbox/scenarios')]);$('#snippet-code').textContent=snippet.data.code;$('#credential-list').innerHTML=developerCredentialHTML(credentials.data);$('#project-deliveries').innerHTML=developerDeliveryHTML(deliveries.data);$('#sandbox-scenario').innerHTML=scenarios.data.map(x=>`<option value="${escapeHTML(x.id||x)}">${escapeHTML(x.name||x)}</option>`).join('');$('#sandbox-sessions').innerHTML=sessions.data.map(x=>`<article><b>${escapeHTML(x.name)}</b><span>${escapeHTML(x.scenario)} · ${x.events.length} events · ${escapeHTML(x.status)}</span></article>`).join('')||'<div class="compact-empty">Belum ada session sandbox.</div>';$('#developer-metrics').innerHTML=[['API keys',credentials.data.filter(x=>!x.revoked_at).length],['Webhook attention',deliveries.data.filter(x=>x.status!=='DELIVERED').length],['Sandbox sessions',sessions.data.length]].map(([label,value])=>`<article><span>${label}</span><b>${value}</b></article>`).join('');document.querySelectorAll('[data-rotate-credential]').forEach(button=>button.onclick=()=>rotateCredential(button.dataset.rotateCredential));document.querySelectorAll('[data-revoke-credential]').forEach(button=>button.onclick=()=>revokeCredential(button.dataset.revokeCredential));document.querySelectorAll('[data-project-delivery]').forEach(button=>button.onclick=()=>replayProjectDelivery(button.dataset.projectDelivery,button));}catch(error){$('#credential-list').innerHTML=`<div class="compact-empty">${escapeHTML(error.message)}</div>`;}}
async function rotateCredential(credentialId){const ok=await openVerificationModal({title:'Rotasi API credential?',description:'Key baru hanya ditampilkan sekali. Key lama tetap aktif selama overlap yang dipilih server.',confirmLabel:'Rotasi credential'});if(!ok)return;try{const {data}=await api(`/admin/api/project-developer/${activeProjectId}/credentials/${credentialId}/rotate`,{method:'POST',body:JSON.stringify({overlap_hours:24})});showNoticeModal({title:'Credential baru dibuat',description:data.secret,tone:'success'});loadDeveloper();}catch(error){showNoticeModal({title:'Rotasi gagal',description:error.message,tone:'error'});}}
async function revokeCredential(credentialId){const ok=await openVerificationModal({title:'Revoke API credential?',description:'Credential langsung tidak dapat dipakai lagi. Tindakan ini tidak dapat dibatalkan.',confirmLabel:'Revoke credential',tone:'danger'});if(!ok)return;try{await api(`/admin/api/project-developer/${activeProjectId}/credentials/${credentialId}`,{method:'DELETE'});loadDeveloper();}catch(error){showNoticeModal({title:'Revoke gagal',description:error.message,tone:'error'});}}
async function replayProjectDelivery(deliveryId,button){button.disabled=true;try{await api(`/admin/api/project-developer/${activeProjectId}/deliveries/${deliveryId}/replay`,{method:'POST'});loadDeveloper();}catch(error){button.disabled=false;showNoticeModal({title:'Replay gagal',description:error.message,tone:'error'});}}
function commerceLinksHTML(items){return items.map(x=>`<article class="commerce-row"><div><b>${escapeHTML(x.title)}</b><span><code>/l/${escapeHTML(x.slug)}</code> · ${x.allow_custom_amount?'Custom amount':money(x.amount)}</span><small>${escapeHTML(x.status)}${x.expires_at?` · expires ${dateTime(x.expires_at)}`:''}</small></div><div><button class="copy-commerce-link" data-link="${escapeHTML(location.origin+x.url)}">Copy</button>${x.status==='ACTIVE'?`<button data-disable-link="${escapeHTML(x.id)}">Disable</button>`:''}</div></article>`).join('')||'<div class="compact-empty">Belum ada payment link.</div>';}
function commerceInvoicesHTML(items){return items.map(x=>`<article class="commerce-row"><div><b>${escapeHTML(x.number)}</b><span>${escapeHTML(x.customer_name||'Customer belum dipilih')} · ${money(x.total_amount)}</span><small>${escapeHTML(x.status)}${x.due_at?` · due ${dateTime(x.due_at)}`:''}</small></div>${['DRAFT','OVERDUE'].includes(x.status)?`<button data-send-invoice="${escapeHTML(x.id)}">Kirim</button>`:`<i>${escapeHTML(x.status)}</i>`}</article>`).join('')||'<div class="compact-empty">Belum ada invoice.</div>';}
async function loadLedgerControl(){if(!activeProjectId)return;try{const [integrity,discrepancies]=await Promise.all([api(`/admin/api/project-reports/${activeProjectId}/ledger-integrity`),api(`/admin/api/project-reports/${activeProjectId}/discrepancies`)]);$('#ledger-integrity').innerHTML=`<div><i class="${integrity.data.valid?'ready':'missing'}">${integrity.data.valid?'✓':'!'}</i><span>${integrity.data.valid?'Ledger integrity valid':integrity.data.issues.length+' integrity issue'} · ${integrity.data.checked} transactions</span></div>`;$('#discrepancy-list').innerHTML=discrepancies.data.map(x=>operationsRow(x.issue_type,`${x.payment_id} · ${dateTime(x.created_at)}`,x.resolution_status,x.resolution_status==='OPEN'?`<button class="resolve-discrepancy quiet" data-id="${x.id}">Investigate</button>`:'')).join('')||'<div class="empty-state"><b>Tidak ada discrepancy</b></div>';document.querySelectorAll('.resolve-discrepancy').forEach(b=>b.onclick=async()=>{await api(`/admin/api/project-reports/${activeProjectId}/discrepancies/${b.dataset.id}`,{method:'PATCH',body:JSON.stringify({status:'INVESTIGATING'})});loadReports();});}catch(error){$('#reconciliation-error').textContent=error.message;}}
async function loadCommerce(){if(!activeProjectId)return;try{const [links,invoices,branding]=await Promise.all([api(`/admin/api/project-commerce/${activeProjectId}/links`),api(`/admin/api/project-commerce/${activeProjectId}/invoices`),api(`/admin/api/project-commerce/${activeProjectId}/branding`)]);$('#payment-link-list').innerHTML=commerceLinksHTML(links.data);$('#invoice-list').innerHTML=commerceInvoicesHTML(invoices.data);for(const [key,value] of Object.entries(branding.data)){const field=$(`#branding-form [name="${key}"]`);if(field)field.value=value||'';}const brand=branding.data;$('#checkout-preview').style.setProperty('--preview-accent',brand.accent_color||'#10ad94');$('#checkout-preview').innerHTML=`<span class="preview-logo">${escapeHTML((brand.display_name||'E').slice(0,1))}</span><b>${escapeHTML(brand.display_name||'Nama project')}</b><small>Secure payment by EvoPay</small><button>Bayar sekarang</button>`;document.querySelectorAll('.copy-commerce-link').forEach(button=>button.onclick=async()=>{try{await navigator.clipboard.writeText(button.dataset.link);button.textContent='Copied ✓';}catch{showNoticeModal({title:'Salin link',description:button.dataset.link});}});document.querySelectorAll('[data-disable-link]').forEach(button=>button.onclick=()=>updateLink(button.dataset.disableLink,{status:'DISABLED'}));document.querySelectorAll('[data-send-invoice]').forEach(button=>button.onclick=()=>sendInvoice(button.dataset.sendInvoice));}catch(error){$('#payment-link-list').innerHTML=`<div class="compact-empty">${escapeHTML(error.message)}</div>`;}}
async function updateLink(id,payload){try{await api(`/admin/api/project-commerce/${activeProjectId}/links/${id}`,{method:'PATCH',body:JSON.stringify(payload)});loadCommerce();}catch(error){showNoticeModal({title:'Payment link gagal diperbarui',description:error.message,tone:'error'});}}
async function sendInvoice(id){try{const {data}=await api(`/admin/api/project-commerce/${activeProjectId}/invoices/${id}/send`,{method:'POST'});showNoticeModal({title:'Invoice dikirim',description:`Portal token: ${data.portal_token}`,tone:'success'});loadCommerce();}catch(error){showNoticeModal({title:'Invoice gagal dikirim',description:error.message,tone:'error'});}}
function reportParams(){return new URLSearchParams(new FormData($('#report-filters'))).toString();}function reportRowsHTML(rows){return rows.slice(0,12).map(x=>`<article class="report-row"><div><b>${escapeHTML(x.merchant_order_id)}</b><span>${escapeHTML(x.payment_method)} · ${dateTime(x.created_at)}</span></div><strong>${money(x.total_amount)}</strong><i class="badge ${escapeHTML(x.status)}">${escapeHTML(x.status)}</i></article>`).join('')||'<div class="compact-empty">Tidak ada transaksi pada filter ini.</div>';}
async function loadReports(){if(!activeProjectId)return;try{const {data}=await api(`/admin/api/project-reports/${activeProjectId}?${reportParams()}`);const s=data.summary;$('#report-metrics').innerHTML=[['Gross volume',money(s.gross)],['Net settlement',money(s.net)],['Platform fee',money(s.fees)],['Success rate',`${Number(s.success_rate).toFixed(1)}%`]].map(([label,value])=>`<article><span>${label}</span><b>${value}</b></article>`).join('');$('#report-methods').innerHTML=data.methods.map(x=>`<article class="report-method"><span>${escapeHTML(x.payment_method)}</span><div><i style="width:${Math.max(4,Number(x.gross)/Math.max(1,Number(s.gross))*100)}%"></i></div><b>${money(x.gross)}</b></article>`).join('')||'<div class="compact-empty">Belum ada channel data.</div>';$('#report-rows').innerHTML=reportRowsHTML(data.rows);$('#reconciliation-status').innerHTML=`<article><span>Ledger entries</span><b>${data.ledger.entries}</b></article><article><span>Ledger balance</span><b>${money(data.ledger.balance)}</b></article><article><span>Checked transactions</span><b>${s.transactions}</b></article>`;await loadLedgerControl();}catch(error){$('#report-rows').innerHTML=`<div class="compact-empty">${escapeHTML(error.message)}</div>`;}}
function riskEventsHTML(items){return items.map(x=>`<article class="control-row"><div><b>${escapeHTML(x.decision)} risk · score ${x.score}</b><span>${dateTime(x.created_at)} · ${x.review_status||'No review required'}</span></div>${x.review_status==='PENDING'?`<div><button data-risk-decision="APPROVED" data-risk-id="${escapeHTML(x.id)}">Approve</button><button class="danger" data-risk-decision="REJECTED" data-risk-id="${escapeHTML(x.id)}">Reject</button></div>`:`<i>${escapeHTML(x.review_status||x.decision)}</i>`}</article>`).join('')||'<div class="compact-empty">Tidak ada risk event untuk project ini.</div>';}
function ticketsHTML(items){return items.map(x=>`<article class="control-row"><div><b>${escapeHTML(x.title)}</b><span>${escapeHTML(x.priority)} · ${x.payment_id?escapeHTML(x.payment_id):'General inspection'} · ${dateTime(x.updated_at)}</span></div><div>${x.status==='OPEN'?`<button data-ticket-status="INVESTIGATING" data-ticket-id="${escapeHTML(x.id)}">Investigate</button>`:''}${x.status==='INVESTIGATING'?`<button data-ticket-status="RESOLVED" data-ticket-id="${escapeHTML(x.id)}">Resolve</button>`:''}<i>${escapeHTML(x.status)}</i></div></article>`).join('')||'<div class="compact-empty">Belum ada inspection ticket.</div>';}
async function loadRiskCenter(){await loadProjectSwitcher();try{const [rules,lists]=await Promise.all([api(`/operations/api/risk/rules?merchant_id=${encodeURIComponent(activeProjectId)}`),api(`/operations/api/risk/lists?merchant_id=${encodeURIComponent(activeProjectId)}`)]);$('#risk-rule-list').innerHTML=rules.data.map(x=>operationsRow(x.name,`${x.signal} ${x.operator} ${x.threshold} · score ${x.score}`,x.action,'')).join('')||'<div class="empty-state"><b>Belum ada rule</b></div>';$('#risk-list').innerHTML=lists.data.map(x=>operationsRow(x.label||x.subject_type,x.subject_type,x.list_type,'')).join('')||'<div class="empty-state"><b>Trust list kosong</b></div>';}catch(error){$('#risk-center-error').textContent=error.message;}}
async function loadOperations(){if(!activeProjectId)return;try{const [risk,tickets]=await Promise.all([api(`/admin/api/project-operations/${activeProjectId}/risk-events`),api(`/admin/api/project-operations/${activeProjectId}/tickets`)]);$('#risk-event-list').innerHTML=riskEventsHTML(risk.data);$('#ticket-list').innerHTML=ticketsHTML(tickets.data);document.querySelectorAll('[data-risk-id]').forEach(button=>button.onclick=()=>reviewRisk(button.dataset.riskId,button.dataset.riskDecision));document.querySelectorAll('[data-ticket-id]').forEach(button=>button.onclick=()=>updateTicket(button.dataset.ticketId,button.dataset.ticketStatus));}catch(error){$('#risk-event-list').innerHTML=`<div class="compact-empty">${escapeHTML(error.message)}</div>`;}}
async function reviewRisk(id,decision){try{await api(`/admin/api/project-operations/${activeProjectId}/risk-events/${id}/review`,{method:'POST',body:JSON.stringify({decision})});loadOperations();}catch(error){showNoticeModal({title:'Risk review gagal',description:error.message,tone:'error'});}}
async function updateTicket(id,status){try{await api(`/admin/api/project-operations/${activeProjectId}/tickets/${id}`,{method:'PATCH',body:JSON.stringify({status})});loadOperations();}catch(error){showNoticeModal({title:'Ticket gagal diperbarui',description:error.message,tone:'error'});}}
function providerHealthHTML(items){return items.map(x=>{const status=x.configured?(x.circuit==='OPEN'||x.success_rate!==null&&x.success_rate<80?'DEGRADED':'HEALTHY'):'NOT CONFIGURED';return `<article class="provider-row"><div class="provider-pulse ${status.toLowerCase().replace(' ','-')}"></div><div><b>${escapeHTML(x.name)}</b><span>${escapeHTML(status)} · ${x.success_rate==null?'No traffic':`${x.success_rate}% success`} · ${x.latency_ms==null?'—':`${x.latency_ms}ms`}</span></div><i>${escapeHTML(x.circuit||'CLOSED')}</i></article>`}).join('')||'<div class="compact-empty">Provider belum terdaftar.</div>';};function routingPoliciesHTML(items){return items.map(x=>`<article class="provider-row"><div><b>${escapeHTML(x.payment_method||'All methods')} → ${escapeHTML(x.provider)}</b><span>Priority ${x.priority} · weight ${x.weight}${x.min_amount?` · min ${money(x.min_amount)}`:''}</span></div><i>ACTIVE</i></article>`).join('')||'<div class="compact-empty">Belum ada override. Default routing berlaku.</div>';};async function loadRouting(){if(!activeProjectId)return;try{const [health,routes,incidents]=await Promise.all([api('/operations/api/providers'),api(`/admin/api/project-routing/${activeProjectId}/routes`),api('/operations/api/incidents')]);$('#provider-health-list').innerHTML=providerHealthHTML(health.data.map(x=>({...x,circuit:x.circuit_state})));$('#routing-policy-list').innerHTML=routingPoliciesHTML(routes.data);$('#provider-incident-list').innerHTML=incidents.data.map(x=>operationsRow(x.title,`${x.provider} · ${x.severity}`,x.status,'')).join('')||'<div class="empty-state"><b>Tidak ada incident aktif</b></div>';}catch(error){$('#provider-health-list').innerHTML=`<div class="compact-empty">${escapeHTML(error.message)}</div>`;}}

function view(name) { document.querySelectorAll('.view').forEach((x) => { x.hidden = x.id !== `${name}-view`; }); document.querySelectorAll('.nav').forEach((x) => x.classList.toggle('active', x.dataset.view === name)); const copy={overview:['Dashboard','Pantau kesehatan bisnis dan arus pembayaran secara real-time.'],payments:['Transaksi','Telusuri, filter, dan tindak lanjuti setiap pembayaran.'],methods:['Metode Pembayaran','Kelola channel Tokopay aktif untuk setiap merchant.'],merchants:['Merchant','Kelola koneksi toko, callback, dan kredensial API.'],webhooks:['Webhooks','Monitor delivery callback dan pulihkan kegagalan dengan cepat.'],ledger:['Mutasi Saldo','Telusuri kredit dan debit pada project aktif.'],payouts:['Penarikan','Kelola rekening tujuan dan ajukan settlement manual.'],developer:['API Playground','Buat request pembayaran dari project aktif.'],commerce:['Links & Invoice','Kelola checkout link, invoice, dan branding project.'],reports:['Reports','Analisis gross volume, fee, dan rekonsiliasi project.'],operations:['Risk & Tickets','Tinjau risiko dan inspeksi operasional project.'],routing:['Provider Routing','Pantau kesehatan provider dan routing pembayaran baru.'],cases:['Dispute','Kelola sengketa pembayaran pada project aktif.'],notices:['Notifikasi','Pantau alert operasional project.'],finance:['Finance','Kendalikan saldo, refund, dan proses settlement.'],analytics:['Analytics','Temukan pola performa dan kualitas konversi pembayaran.'],'ip-whitelist':['Whitelist IP','Kelola daftar IP yang diizinkan mengakses API.'],audit:['Audit log','Jejak aktivitas sensitif dan perubahan sistem.'],onboarding:['KYC & Production','Identitas bisnis, review dokumen, dan production activation.'],approvals:['Approvals','Dual control dan policy tindakan finansial sensitif.'],'case-detail':['Detail Dispute','Timeline, evidence checklist, dan SLA chargeback.'],risk:['Risk Engine','Rule, trust list, simulation, dan review queue.']}[name];$('#view-title').textContent=copy[0];$('#view-subtitle').textContent=copy[1]; if(name==='overview')overview();if(name==='payments'){populateMerchantFilter();loadPayments();}if(name==='methods')paymentMethods();if(name==='merchants')merchants();if(name==='webhooks')loadWebhooks();if(name==='ledger')loadLedger();if(name==='payouts')loadPayouts();if(name==='developer')loadDeveloper();if(name==='commerce')loadCommerce();if(name==='reports')loadReports();if(name==='operations')loadOperations();if(name==='routing')loadRouting();if(name==='cases')loadCases();if(name==='notices')loadNotices();if(name==='finance')loadFinance();if(name==='analytics')loadAnalytics();if(name==='ip-whitelist')loadIpRules();if(name==='audit')loadAudit();if(name==='onboarding')loadOnboarding();if(name==='approvals')loadApprovals();if(name==='risk')loadRiskCenter(); }
async function copyKey(key, button) { try { await navigator.clipboard.writeText(key); button.textContent = 'Copied ✓'; setTimeout(() => { button.textContent = 'Copy API key'; }, 1500); } catch { showNoticeModal({title:'Salin API key secara manual',description:'Clipboard tidak tersedia. Pilih dan salin API key berikut.',content:`<code class="notice-code">${escapeHTML(key)}</code>`}); } }
const dateTime=(value)=>value?new Date(value).toLocaleString('id-ID',{dateStyle:'medium',timeStyle:'medium'}):'—';
const transactionField=(label,value,{mono=false,copy=false}={})=>`<div class="transaction-field"><span>${escapeHTML(label)}</span><b class="${mono?'mono-value':''}">${escapeHTML(value??'—')}${copy&&value?` <button class="inline-copy" type="button" data-copy-value="${escapeHTML(value)}" aria-label="Salin ${escapeHTML(label)}">□</button>`:''}</b></div>`;
const transactionCard=(title,content,className='')=>`<section class="transaction-card ${className}"><h3>${escapeHTML(title)}</h3>${content}</section>`;
function transactionSummaryHTML(p){return transactionCard('Ringkasan Transaksi',`<div class="transaction-fields">${transactionField('ID',p.id,{mono:true,copy:true})}${transactionField('Merchant ID',p.merchant_id,{mono:true,copy:true})}${transactionField('Kategori','Payment')}${transactionField('Channel',p.payment_method,{mono:true})}${transactionField('Provider',p.provider)}${transactionField('Redirect URL',p.redirect_url||p.checkout_url,{mono:true})}</div>`);}
function paymentAmountsHTML(p){return transactionCard('Detail Pembayaran',`<div class="amount-summary"><div><span>Nominal</span><strong>${money(p.amount)}</strong></div><div><span>Jumlah Bayar</span><strong>${money(p.total_amount)}</strong></div><div class="positive"><span>Jumlah Diterima</span><strong>${money(p.net_amount)}</strong></div><div class="negative"><span>Biaya Admin</span><strong>${money(p.fee_amount)}</strong></div></div>`);}
function customerDetailHTML(p){return transactionCard('Data Customer',`<div class="transaction-fields three">${transactionField('Nama',p.customer?.name)}${transactionField('Email',p.customer?.email)}${transactionField('Telepon',p.customer?.phone)}</div>`);}
function transactionTimeHTML(p){let expiryHint='';if(p.expires_at&&p.status==='PENDING'){const minutes=Math.max(0,Math.ceil((new Date(p.expires_at)-Date.now())/60000));expiryHint=`<em>${minutes?`dalam ${minutes} menit`:'sudah berakhir'}</em>`;}return transactionCard('Waktu',`<div class="transaction-fields three">${transactionField('Dibuat',dateTime(p.created_at))}${transactionField(p.paid_at?'Dibayar':'Diperbarui',dateTime(p.paid_at||p.updated_at))}<div class="transaction-field"><span>Expired</span><b>${escapeHTML(dateTime(p.expires_at))}</b>${expiryHint}</div></div>`);}
function settlementSummaryHTML(p){const released=p.status==='PAID';return transactionCard('Status Dana',`<div class="fund-status"><span class="fund-pill ${released?'released':'waiting'}">${released?'● Released':'◷ Menunggu'}</span><div>${transactionField(released?'Tanggal Rilis':'Status Transaksi',released?dateTime(p.paid_at):p.status)}</div><div>${transactionField('Jumlah Bersih',money(p.net_amount))}</div><div>${transactionField('Provider',p.provider)}</div></div>`,'transaction-side-card');}
function productDetailHTML(p){return transactionCard('Data Produk (1)',`<article class="product-detail"><div><b>${escapeHTML(p.description||`Pembayaran ${p.order_id}`)}</b><span>Order ID</span><code>${escapeHTML(p.order_id)}</code></div><strong>${money(p.amount)}</strong><div class="product-meta"><span>Channel <b>${escapeHTML(p.payment_method)}</b></span><span>TRX ID <b>${escapeHTML(p.provider_transaction_id||'—')}</b></span></div></article>`,'transaction-side-card');}
function webhookLogHTML(deliveries){const rows=(deliveries||[]).map((item)=>`<tr><td><code>${escapeHTML(item.id)}</code></td><td><span class="webhook-http ${item.response_code>=200&&item.response_code<300?'success':''}">${item.response_code||'—'}</span></td><td>${escapeHTML(item.status)}</td><td>${item.attempt_count}</td><td>${item.status!=='DELIVERED'?`<button class="retry-delivery" data-delivery-id="${escapeHTML(item.id)}">Retry</button>`:'<span class="delivery-ok">Delivered</span>'}</td></tr>`).join('');return transactionCard('Log Webhook',rows?`<div class="webhook-table-wrap"><table class="webhook-table"><thead><tr><th>ID</th><th>HTTP</th><th>Status</th><th>Attempt</th><th>Aksi</th></tr></thead><tbody>${rows}</tbody></table></div>`:'<div class="compact-empty">Belum ada webhook delivery.</div>','transaction-side-card');}
function transactionActivityHTML(events){const content=(events||[]).map((event)=>`<article class="transaction-event"><i></i><div><b>${escapeHTML(event.event_type)}</b><span>${dateTime(event.created_at)} · ${event.signature_valid===0?'invalid signature':escapeHTML(event.provider)}</span></div></article>`).join('');return transactionCard('Aktivitas Provider',content||'<div class="compact-empty">Belum ada event provider.</div>');}
function refundsHTML(refunds){return transactionCard('Refund',refunds.length?refunds.map((item)=>`<article class="transaction-list-row"><div><b>${escapeHTML(item.reason||'Refund')}</b><span>${dateTime(item.created_at)}</span></div><strong>${money(item.amount)}</strong><i class="badge ${escapeHTML(item.status)}">${escapeHTML(item.status)}</i></article>`).join(''):'<div class="compact-empty">Belum ada refund.</div>');}
function notesHTML(notes){return transactionCard('Catatan Internal',`${notes.map((note)=>`<article class="transaction-note"><b>${escapeHTML(note.author_name||'Operator')}</b><p>${escapeHTML(note.body)}</p><span>${dateTime(note.created_at)}</span></article>`).join('')}<form id="payment-note-form" class="note-form transaction-note-form"><input name="body" required maxlength="500" placeholder="Tambahkan catatan internal"><button>Tambah catatan</button></form>`);}
async function openPayment(paymentId){selectedPaymentId=paymentId;$('#payment-modal').hidden=false;$('#payment-detail').innerHTML='<div class="loading-state">Memuat detail transaksi…</div>';$('#payment-action-error').textContent='';$('#payment-header-actions').innerHTML='';try{const {data}=await api(`/admin/api/payments/${paymentId}`),p=data.payment,deliveries=data.deliveries||[],refunds=data.refunds||[],notes=data.notes||[];$('#payment-modal-title').textContent=`Transaksi ${p.order_id}`;$('#payment-modal-status').textContent=p.status;$('#payment-modal-status').className=`badge ${p.status}`;$('#payment-modal-date').textContent=dateTime(p.created_at);$('#payment-modal-reference').textContent=`Ref: ${p.reference||'—'}`;const retryable=deliveries.find((item)=>item.status!=='DELIVERED');$('#payment-header-actions').innerHTML=`${p.status==='PENDING'?'<button class="transaction-action" id="sync-selected-payment">↻ Reload</button>':''}${retryable?`<button class="transaction-action primary retry-delivery" data-delivery-id="${escapeHTML(retryable.id)}">↗ Kirim Webhook</button>`:''}${p.status==='PAID'?'<button class="transaction-action danger" id="refund-selected-payment">↩ Refund</button>':''}`;$('#payment-detail').innerHTML=`<div class="transaction-layout"><main class="transaction-main">${transactionSummaryHTML(p)}${paymentAmountsHTML(p)}${customerDetailHTML(p)}${transactionTimeHTML(p)}${transactionActivityHTML(data.events||[])}${refundsHTML(refunds)}${notesHTML(notes)}</main><aside class="transaction-aside">${settlementSummaryHTML(p)}${productDetailHTML(p)}${webhookLogHTML(deliveries)}</aside></div>`;$('#sync-selected-payment')?.addEventListener('click',syncSelectedPayment);$('#refund-selected-payment')?.addEventListener('click',refundSelectedPayment);$('#payment-note-form').onsubmit=addPaymentNote;document.querySelectorAll('.retry-delivery').forEach((button)=>button.onclick=()=>retryDelivery(button.dataset.deliveryId,button));document.querySelectorAll('.inline-copy').forEach((button)=>button.onclick=()=>copyInlineValue(button));}catch(error){$('#payment-detail').innerHTML=`<div class="empty-state"><b>Detail transaksi tidak dapat dimuat</b><span>${escapeHTML(error.message)}</span></div>`;}}
async function copyInlineValue(button){try{await navigator.clipboard.writeText(button.dataset.copyValue);button.textContent='✓';setTimeout(()=>button.textContent='□',1200);}catch{showNoticeModal({title:'Salin nilai secara manual',description:button.dataset.copyValue});}}
async function syncSelectedPayment() { const button = $('#sync-selected-payment'); button.disabled = true; button.textContent = 'Synchronizing…'; try { await api(`/admin/api/payments/${selectedPaymentId}/sync`, { method: 'POST' }); await Promise.all([openPayment(selectedPaymentId), loadPayments(), overview()]); } catch (error) { $('#payment-action-error').textContent = error.message; button.disabled = false; button.textContent = '↻ Sync with Tokopay'; } }
function refundSelectedPayment(){openRefundModal();}
async function addPaymentNote(event){event.preventDefault();const body=new FormData(event.target).get('body');await api(`/admin/api/payments/${selectedPaymentId}/notes`,{method:'POST',body:JSON.stringify({body})});await openPayment(selectedPaymentId);}
async function retryDelivery(deliveryId, button) { button.disabled = true; button.textContent = 'Queued…'; try { await api(`/admin/api/deliveries/${deliveryId}/retry`, { method: 'POST' }); setTimeout(() => openPayment(selectedPaymentId), 800); } catch (error) { $('#payment-action-error').textContent = error.message; button.disabled = false; button.textContent = 'Retry callback'; } }

$('#login-form').onsubmit = async (event) => { event.preventDefault(); const button = $('#login-button'); button.disabled = true; $('#login-error').textContent=''; try { const {data}=await api('/admin/api/login', { method: 'POST', body: JSON.stringify({ username: $('#username').value, password: $('#password').value }) }); $('#username').value=''; $('#password').value=''; showDashboard(data.user); } catch (error) { $('#login-error').textContent = error.message; } finally { button.disabled = false; } };
function showAuthPane(register){$('#login-pane').hidden=register;$('#register-pane').hidden=!register;$('#show-login').classList.toggle('active',!register);$('#show-register').classList.toggle('active',register);$('#show-login').setAttribute('aria-selected',String(!register));$('#show-register').setAttribute('aria-selected',String(register));(register?$('#register-name'):$('#username')).focus();}$('#show-login').onclick=()=>showAuthPane(false);$('#show-register').onclick=()=>showAuthPane(true);$('#register-form').onsubmit=async event=>{event.preventDefault();const button=$('#register-button'),body=Object.fromEntries(new FormData(event.target));button.disabled=true;$('#register-error').textContent='';try{const {data}=await api('/admin/api/register',{method:'POST',body:JSON.stringify(body)});event.target.reset();showDashboard(data.user);}catch(error){$('#register-error').textContent=error.message;}finally{button.disabled=false;}};
function authPanel(name){for(const pane of ['login','register','forgot'])$(`#${pane}-pane`).hidden=pane!==name;if(name==='login')$('#username').focus();if(name==='forgot')$('#forgot-email').focus();}$('#show-forgot').onclick=()=>authPanel('forgot');$('#back-to-login').onclick=()=>authPanel('login');$('#forgot-form').onsubmit=async event=>{event.preventDefault();const b=$('#forgot-button');b.disabled=true;$('#forgot-error').textContent='';try{await api('/admin/api/forgot-password',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(event.target)))});$('#forgot-error').textContent='Jika email terdaftar, tautan reset telah dikirim.';}catch(error){$('#forgot-error').textContent=error.message;}finally{b.disabled=false;}};async function loadIdentityStatus(){try{const {data}=await api('/admin/api/identity/status');$('#identity-status').innerHTML=`<b>Email ${data.email_verified?'terverifikasi':'belum diverifikasi'}</b><span> · 2FA ${data.totp_enabled?'aktif':'belum aktif'}</span>`;$('#send-verification').hidden=data.email_verified;$('#setup-totp').hidden=data.totp_enabled;$('#disable-totp').hidden=!data.totp_enabled;}catch(error){$('#identity-error').textContent=error.message;}}function closePasswordModal(){$('#password-modal').hidden=true;}$('.avatar-button').onclick=()=>{$('#change-password-form').reset();$('#change-password-error').textContent='';$('#identity-error').textContent='';$('#password-modal').hidden=false;loadIdentityStatus();};$('#send-verification').onclick=async()=>{try{const {data}=await api('/admin/api/identity/verification/send',{method:'POST'});$('#identity-error').textContent=data.message;}catch(error){$('#identity-error').textContent=error.message;}};$('#setup-totp').onclick=async()=>{try{const {data}=await api('/admin/api/identity/totp/setup',{method:'POST'});$('#totp-secret').value=data.secret;$('#totp-setup').hidden=false;}catch(error){$('#identity-error').textContent=error.message;}};$('#enable-totp').onclick=async()=>{try{const {data}=await api('/admin/api/identity/totp/enable',{method:'POST',body:JSON.stringify({code:$('#totp-code').value})});$('#totp-setup').hidden=true;$('#recovery-codes').hidden=false;$('#recovery-codes').textContent='Simpan recovery codes ini:\n'+data.recovery_codes.join('\n');loadIdentityStatus();}catch(error){$('#identity-error').textContent=error.message;}};$('#disable-totp').onclick=()=>{$('#security-code-form').reset();$('#security-code-error').textContent='';$('#security-code-modal').hidden=false;$('#security-code-input').focus();};$('#close-security-code').onclick=()=>{$('#security-code-modal').hidden=true;};$('#security-code-form').onsubmit=async event=>{event.preventDefault();try{await api('/admin/api/identity/totp/disable',{method:'POST',body:JSON.stringify({code:$('#security-code-input').value})});$('#security-code-modal').hidden=true;loadIdentityStatus();}catch(error){$('#security-code-error').textContent=error.message;}};$('#close-password-modal').onclick=closePasswordModal;$('#change-password-form').onsubmit=async event=>{event.preventDefault();const b=$('#change-password-button');b.disabled=true;$('#change-password-error').textContent='';try{await api('/admin/api/change-password',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(event.target)))});location.reload();}catch(error){$('#change-password-error').textContent=error.message;b.disabled=false;}};const verifyToken=new URLSearchParams(location.search).get('verify');if(verifyToken){api('/admin/api/identity/verification/confirm',{method:'POST',body:JSON.stringify({token:verifyToken})}).then(()=>{history.replaceState({},'',location.pathname);$('#login-error').textContent='Email berhasil diverifikasi. Silakan masuk.';}).catch(error=>{$('#login-error').textContent=error.message;});}const resetToken=new URLSearchParams(location.search).get('reset');if(resetToken){$('#login').hidden=false;$('#dashboard').hidden=true;$('#reset-modal').hidden=false;}$('#reset-password-form').onsubmit=async event=>{event.preventDefault();const b=$('#reset-password-button');b.disabled=true;$('#reset-password-error').textContent='';try{await api('/admin/api/reset-password',{method:'POST',body:JSON.stringify({...Object.fromEntries(new FormData(event.target)),token:resetToken})});history.replaceState({},'',location.pathname);$('#reset-modal').hidden=true;authPanel('login');$('#login-error').textContent='Password berhasil direset. Silakan masuk.';}catch(error){$('#reset-password-error').textContent=error.message;b.disabled=false;}};
document.querySelectorAll('[data-view]').forEach((button) => { button.onclick = () => view(button.dataset.view); }); $('#logout').onclick = async () => { try { await api('/admin/api/logout', { method: 'POST' }); } finally { location.reload(); } };
$('#payment-filters').onchange = () => { paymentState.page = 1; loadPayments(); }; $('#payment-search').oninput = () => { clearTimeout(searchTimer); searchTimer = setTimeout(() => { paymentState.page = 1; loadPayments(); }, 350); };
$('#reset-payment-filters').onclick = () => { $('#payment-filters').reset(); $('#payment-search').value = ''; clearTimeout(searchTimer); paymentState.page = 1; loadPayments(); }; $('#export-payments').onclick = () => { location.href = `/admin/api/payments/export.csv?${filterParams(false)}`; }; $('#payments-prev').onclick = () => { if (paymentState.page > 1) { paymentState.page -= 1; loadPayments(); } }; $('#payments-next').onclick = () => { if (paymentState.page < paymentState.pages) { paymentState.page += 1; loadPayments(); } };
